/* The Mac Home, chat list and Chief rules for the app (cmux-tui/crates/cmux-app-ffi,
 * src/home.rs): the JSON ops of cmux-home-rules, run by cmux_home_call. */

#ifndef CMUX_HOME_H
#define CMUX_HOME_H

/* Generated by cbindgen (cmux-tui/crates/cmux-app-ffi/cbindgen-home.toml); do not edit.
 * Regenerate: CMUX_APP_FFI_HEADER_BLESS=1 cargo test --test home_header (cmux-app-ffi) */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/*
 Bumped on any change to a type, a function or an op.
 */
#define CMUX_HOME_ABI_VERSION 1

/*
 The op ran; `*out` holds its reply.
 */
#define CMUX_HOME_OK 0

/*
 A null pointer where one is required.
 */
#define CMUX_HOME_ERR_NULL -1

/*
 Not UTF-8, or not the JSON the op takes.
 */
#define CMUX_HOME_ERR_INVALID -2

/*
 The op is not one of cmux_home_rules's.
 */
#define CMUX_HOME_ERR_UNKNOWN_OP -3

/*
 A panic inside, caught.
 */
#define CMUX_HOME_ERR_PANIC -4

/*
 A reply buffer owned by the caller (JSON, UTF-8). `ptr` is null when `len`
 is 0.
 */
typedef struct {
    uint8_t *ptr;
    size_t len;
} CmuxHomeBytes;

/*
 `CMUX_HOME_ABI_VERSION`.
 */
uint32_t cmux_home_abi_version(void);

/*
 Runs one JSON op: `op` (NUL-terminated, such as `inbox.sections`) on
 `request` (a JSON object, UTF-8); `*out` gets the reply's JSON, which the
 caller frees with `cmux_home_bytes_free`.

 # Safety

 `op` is a NUL-terminated string; `request_ptr` with `request_len` is
 readable; `out` is writable.
 */
int32_t cmux_home_call(const char *op, const uint8_t *request_ptr, size_t request_len, CmuxHomeBytes *out);

/*
 Frees a reply buffer. A null `ptr` is ignored.

 # Safety

 `bytes` came from `cmux_home_call` and is freed once.
 */
void cmux_home_bytes_free(CmuxHomeBytes bytes);

#endif  /* CMUX_HOME_H */
